"""make keys must never show a value, whole or as any 6-character slice."""

import random
import string

import check_keys
import httpx
import pymongo
import pytest

from paperghosts import config

rng = random.Random(1850)


def rand(n, chars=string.ascii_letters + string.digits):
    return "".join(rng.choices(chars, k=n))


def hexes(n):
    return rand(n, "0123456789abcdef")


def digits(n):
    return rand(n, string.digits)


# shaped like the real values, so each check runs as far as its call
CANARIES = {
    "TINKER_API_KEY": "tml-" + rand(60),
    "MONGODB_URI": f"REDACTED",
    "RENDER_API_KEY": "rnd_" + rand(28),
    "SENTRY_DSN": f"https://{hexes(32)}@o{digits(7)}.ingest.us.sentry.io/{digits(7)}",
    "SENTRY_DSN_WEB": f"https://{hexes(32)}@o{digits(7)}.ingest.us.sentry.io/{digits(7)}",
    "SENTRY_AUTH_TOKEN": "sntryu_" + hexes(64),
    "SENTRY_ORG": hexes(8),
    "SENTRY_PROJECT": hexes(15),
    "SERPAPI_API_KEY": hexes(64),
    "PAPERINSTRUMENTS_API_KEY": rand(46),
    "ULTRAMARINE_BASE_URL": f"https://{hexes(10)}.example.com/v1",
    "ULTRAMARINE_MODEL": hexes(19),
    "HF_TOKEN": "hf_" + rand(34),
    "GEMINI_API_KEY": rand(53),
    "ELEVENLABS_API_KEY": rand(51),
    "TABPFN_TOKEN": rand(53),
}


def echo(*args, **kwargs):
    # what a careless library error or a hostile server quotes back: everything it was given
    return f"{args} {kwargs}"


@pytest.mark.parametrize("mode", ["raise", "reject", "accept"])
def test_make_keys_never_shows_a_value(mode, tmp_path, monkeypatch, capfd):
    env = tmp_path / ".env"
    env.write_text("".join(f"{name}={value}\n" for name, value in CANARIES.items()))
    monkeypatch.setattr(config, "ENV_FILE", env)
    for name in {*CANARIES, *check_keys.KEYS}:
        monkeypatch.delenv(name, raising=False)

    def get(url, **kwargs):
        if mode == "raise":
            raise httpx.ConnectError(echo(url, **kwargs))
        if mode == "reject":
            return httpx.Response(401, text=echo(url, **kwargs))
        # real bodies carry account details too; SerpApi's even repeats the key
        said = echo(url, **kwargs)
        return httpx.Response(200, json={"total_searches_left": 250, "data": [said], "api_key": said})

    class Mongo:
        def __init__(self, uri, **kwargs):
            if mode == "raise":
                raise pymongo.errors.ConfigurationError(echo(uri, **kwargs))
            self.admin, self.uri = self, uri

        def __enter__(self):
            return self

        def __exit__(self, *exc):
            return False

        def command(self, name):
            if mode == "reject":
                raise pymongo.errors.OperationFailure(echo(self.uri, name))
            return {"authInfo": {"authenticatedUsers": [{"user": echo(self.uri), "db": "admin"}]}}

    monkeypatch.setattr(httpx, "get", get)
    monkeypatch.setattr(pymongo, "MongoClient", Mongo)

    try:
        code, crash = check_keys.main(), ""
    except Exception as exc:  # a crash must not quote a value either
        code, crash = None, repr(exc)
    out, err = capfd.readouterr()
    shown = out + err + crash + "".join(f"{s!r} {s}" for s in map(config.setting, check_keys.KEYS))

    leaked = [n for n, v in CANARIES.items() if any(v[i : i + 6] in shown for i in range(len(v) - 5))]
    assert leaked == []
    assert code == (0 if mode == "accept" else 1)

"""Settings from the environment, falling back to the repo's .env.

Values come back wrapped in Secret, so printing or logging one never shows it.
"""

import os
from pathlib import Path

ENV_FILE = Path(__file__).resolve().parents[1] / ".env"

# The owner's .env names the Ultramarine key PAPERINSTRUMENTS_API_KEY (decision 12).
ALIASES = {"ULTRAMARINE_API_KEY": "PAPERINSTRUMENTS_API_KEY"}


class Secret:
    """A setting's value; repr, str and f-strings show only whether it is set."""

    __slots__ = ("_value",)

    def __init__(self, value: str) -> None:
        self._value = value

    def get(self) -> str:
        return self._value

    def __bool__(self) -> bool:
        return bool(self._value)

    def __repr__(self) -> str:
        return "Secret(set)" if self._value else "Secret(empty)"

    __str__ = __repr__


def read_env_file(path: Path) -> dict[str, str]:
    """KEY=VALUE pairs; blanks, # comments and lines without = are skipped."""
    values = {}
    if path.is_file():
        for line in path.read_text().splitlines():
            name, eq, value = line.strip().partition("=")
            if not eq or name.startswith("#"):
                continue
            value = value.strip()
            if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
                value = value[1:-1]
            values[name.strip()] = value
    return values


def setting(name: str) -> Secret:
    """The environment wins over .env, so Render's settings apply where there is no .env."""
    file = read_env_file(ENV_FILE)
    for key in (name, ALIASES.get(name)):
        if key and (value := os.environ.get(key) or file.get(key)):
            return Secret(value)
    return Secret("")

"""make keys: a shape check, then one cheap authenticated call, for each key the build uses.

Prints each name with OK, FAIL or EMPTY and a reason, never a value. Exits 1 if a check
fails or a required key is empty. Unused keys are only reported as present or empty.
"""

import re
import sys
from urllib.parse import urlsplit

import httpx
import pymongo

from paperghosts.config import setting

REQUIRED, OPTIONAL, UNUSED = "required", "optional", "unused"
TINKER = "https://tinker.thinkingmachines.dev/services/tinker-prod"


class Failed(Exception):
    """A failure told with fixed text and status codes only, so it is safe to print."""


def get(url, **kwargs):
    response = httpx.get(url, timeout=10, **kwargs)
    if response.status_code != 200:
        raise Failed(f"HTTP {response.status_code}")
    return response.json()


def bearer(token):
    return {"Authorization": f"Bearer {token}"}


def matches(pattern):
    return lambda value: re.fullmatch(pattern, value) is not None


def mongo_uri(value):
    url = urlsplit(value)
    has_login = bool(url.username and url.password and url.hostname)
    return url.scheme in ("mongodb", "mongodb+srv") and has_login


def sentry_dsn(value):
    url = urlsplit(value)
    return (
        url.scheme == "https"
        and re.fullmatch("[0-9a-f]{32}", url.username or "") is not None
        and (url.hostname or "").endswith(".sentry.io")
        and url.path.strip("/").isdigit()
    )


def https_url(value):
    url = urlsplit(value)
    return url.scheme == "https" and bool(url.hostname)


def tinker(key):
    # the route `tinker auth login` checks keys with; no SDK import, no session
    get(f"{TINKER}/api/v1/auth/apikey/me", headers={"X-API-Key": key})
    return "key accepted"


def atlas(uri):
    with pymongo.MongoClient(uri, serverSelectionTimeoutMS=10_000) as client:
        status = client.admin.command("connectionStatus")
    if not status["authInfo"]["authenticatedUsers"]:
        raise Failed("connected, but not authenticated")
    return "authenticated"


def render(key):
    get("https://api.render.com/v1/owners", params={"limit": 1}, headers=bearer(key))
    return "key accepted"


def sentry(token):
    org, project = setting("SENTRY_ORG").get(), setting("SENTRY_PROJECT").get()
    get(f"https://sentry.io/api/0/projects/{org}/{project}/", headers=bearer(token))
    return "project readable"


def serpapi(key):
    # the account endpoint uses no searches
    account = get("https://serpapi.com/account.json", params={"api_key": key})
    return f"{int(account['total_searches_left'])} searches left"


def ultramarine(key):
    base = setting("ULTRAMARINE_BASE_URL").get().rstrip("/")
    if not base:
        raise Failed("ULTRAMARINE_BASE_URL is empty")
    models = get(f"{base}/models", headers=bearer(key))
    return f"{len(models['data'])} models listed"


def huggingface(token):
    get("https://huggingface.co/api/whoami-v2", headers=bearer(token))
    return "token accepted"


SLUG = r"[a-z0-9][a-z0-9_-]*"

# name: (need, shape, cheap authenticated call)
KEYS = {
    "TINKER_API_KEY": (REQUIRED, matches(r"tml-[\w-]{20,}"), tinker),
    "MONGODB_URI": (REQUIRED, mongo_uri, atlas),
    "RENDER_API_KEY": (REQUIRED, matches(r"rnd_[A-Za-z0-9]{20,}"), render),
    # a DSN can only prove itself by sending an event, which phase1_env does
    "SENTRY_DSN": (REQUIRED, sentry_dsn, None),
    "SENTRY_DSN_WEB": (REQUIRED, sentry_dsn, None),
    "SENTRY_AUTH_TOKEN": (
        REQUIRED,
        matches(r"sntryu_[0-9a-f]{64}|sntrys_\S{20,}|[0-9a-f]{64}"),
        sentry,
    ),
    "SENTRY_ORG": (REQUIRED, matches(SLUG), None),
    "SENTRY_PROJECT": (REQUIRED, matches(SLUG), None),
    "SERPAPI_API_KEY": (OPTIONAL, matches(r"[0-9a-f]{64}"), serpapi),
    "ULTRAMARINE_API_KEY": (OPTIONAL, matches(r"\S{20,}"), ultramarine),
    "ULTRAMARINE_BASE_URL": (OPTIONAL, https_url, None),
    "ULTRAMARINE_MODEL": (OPTIONAL, matches(r"\S+"), None),
    "HF_TOKEN": (OPTIONAL, matches(r"hf_[A-Za-z0-9]{30,}"), huggingface),
    "GEMINI_API_KEY": (UNUSED, None, None),
    "ELEVENLABS_API_KEY": (UNUSED, None, None),
    "TABPFN_TOKEN": (UNUSED, None, None),
}


def check(name):
    need, shape, call = KEYS[name]
    value = setting(name).get()
    if not value:
        return "EMPTY", need
    if need == UNUSED:
        return "OK", "present, unused, so not called"
    try:
        shaped = shape(value)
    except ValueError:  # urlsplit rejects some malformed URLs outright
        shaped = False
    if not shaped:
        return "FAIL", "unexpected shape"
    if call is None:
        return "OK", "shape ok"
    try:
        return "OK", f"shape ok, {call(value)}"
    except Failed as exc:
        return "FAIL", f"shape ok, {exc}"
    except Exception as exc:  # library messages can quote the key, URL or URI
        return "FAIL", f"shape ok, call raised {type(exc).__name__}"


def main():
    failed = False
    for name, (need, _, _) in KEYS.items():
        status, reason = check(name)
        print(f"{name:<22} {status:<5}  {reason}")
        failed |= status == "FAIL" or (status == "EMPTY" and need == REQUIRED)
    return int(failed)


if __name__ == "__main__":
    sys.exit(main())

